script:
(function () {
  'use strict';
  // ===== Tax figures: tax year 2026 =====
  // Ordinary brackets, capital gains breakpoints and standard deductions: IRS Rev. Proc. 2025-32,
  // sections 4.01, 4.03 and 4.14 (2026 inflation adjustments, as amended by P.L. 119-21).
  // Unrecaptured section 1250 gain: maximum 25% rate, IRC 1(h)(1)(E); worksheet method from the
  // Schedule D Tax Worksheet (2025 Instructions for Schedule D), whose line 19 is the top of the
  // 24% bracket. Net investment income tax: IRC 1411, 3.8%; thresholds are not indexed.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj: [24800, 100800, 211400, 403550, 512450, 768700],
    hoh: [17700, 67450, 105700, 201750, 256200, 640600],
    mfs: [12400, 50400, 105700, 201775, 256225, 384350]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { // taxable income where the 0% rate ends and the 15% rate ends
    single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850]
  };
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var NIIT_RATE = 0.038;
  var NIIT_THRESHOLD = { single: 200000, mfj: 250000, mfs: 125000, hoh: 200000 };
  var STATE_RATE_MAX = 15;
  // ======================================
  // Method: tax if you sold outright = federal tax with the gain - federal tax without it (both from
  // the Schedule D Tax Worksheet: ordinary income first, then unrecaptured 1250 gain taxed at regular
  // rates up to the 24% bracket and 25% above it, then the rest of the long-term gain at 0/15/20%, the
  // result capped at regular tax on everything) + NIIT (3.8% of the smaller of the gain and MAGI over
  // the threshold, MAGI = other income + gain) + flat state rate x gain.
  //   Realized gain = sale price - selling costs - (cost + improvements - depreciation);
  //   unrecaptured 1250 gain = min(depreciation, gain); the rest is long-term capital gain.
  // A full exchange defers that whole tax. Its present value if paid at the end of the holding period
  // = tax / (1 + r)^years (zero if the property is held until death and gets a stepped-up basis);
  // value of deferral today = tax - present value; growth on the tax kept invested = tax x ((1 + r)^years - 1).
  // Verified (Node, scratchpad lkrepo/tests/lk.test.js): the worksheet matches an independent IRC 1(h)
  //   bracket-stacking model on 20,000 random cases (all statuses, incl. deductions above income);
  //   rate-table checks single $92,000 = $14,952 and MFJ $211,400 = $35,932 (Rev. Proc. table).
  //   Defaults (single, $120,000 other income, $900,000 sale, $500,000 cost, $50,000 improvements,
  //   $150,000 depreciation, $54,000 costs): gain $446,000; federal $80,885 by hand ($396 at 22% +
  //   $23,058 at 24% on 1250 gain up to the 24% top, $44,400 at 15% on $296,000, $13,031 at 25% on the
  //   last $52,125 of 1250 gain); NIIT $13,908 (3.8% of $366,000 over $200,000); 5% state $22,300;
  //   total $117,093; 10 years at 6% -> present value $65,384, growth $92,603. $100,000 LTCG with no
  //   other income -> $7,583 (15% of $50,550). Blank, fractional or out-of-range input shows an error.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pctFmt = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function regTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  // Schedule D Tax Worksheet with no qualified dividends, 28% gain or Form 4952 amounts.
  // taxable = line 1; u = unrecaptured 1250 gain; c = other net long-term gain (u, c >= 0).
  function fedTax(status, taxable, u, c) {
    var L1 = Math.max(0, taxable);
    if (L1 <= 0) return 0;
    if (u + c <= 0) return regTax(L1, status);
    var L10 = u + c, L13 = L10 - Math.min(L10, u);
    var L14 = Math.max(0, L1 - L13);
    var L16 = Math.min(L1, CG_BREAKS[status][0]), L17 = Math.min(L14, L16);
    var L18 = Math.max(0, L1 - L10);
    var L20 = Math.min(L14, Math.min(L1, BRACKETS[status][3]));
    var L21 = Math.max(L18, L20), L22 = L16 - L17;
    var L23 = Math.min(L1, L13), L25 = Math.max(0, L23 - L22);
    var L29 = Math.max(0, Math.min(L1, CG_BREAKS[status][1]) - (L21 + L22));
    var L30 = Math.min(L25, L29), L33 = Math.max(0, L23 - (L22 + L30));
    var L38 = Math.max(0, L10 + L21 - L1), L39 = Math.max(0, Math.min(L10, u) - L38);
    var L45 = 0.15 * L30 + 0.20 * L33 + 0.25 * L39 + regTax(L21, status);
    return Math.min(L45, regTax(L1, status));
  }

  function saleTax(p) {
    var adjBasis = p.cost + p.improve - p.dep;
    var gain = p.sale - p.sellCost - adjBasis;
    var g = Math.max(0, gain), u = Math.min(p.dep, g), c = g - u;
    var ordinary = p.income - p.deduction;
    var without = fedTax(p.status, ordinary, 0, 0);
    var withGain = fedTax(p.status, ordinary + g, u, c);
    var fed = withGain - without;
    var niit = p.niit ? NIIT_RATE * Math.min(g, Math.max(0, p.income + g - NIIT_THRESHOLD[p.status])) : 0;
    var state = p.stateRate * g;
    return { adjBasis: adjBasis, gain: gain, u: u, c: c, fed: fed, niit: niit, state: state, total: fed + niit + state };
  }

  function deferral(tax, rate, years, stepUp) {
    var growth = Math.pow(1 + rate, years);
    var pv = stepUp ? 0 : tax / growth;
    var rows = [];
    for (var y = 1; y <= years; y++) {
      var g = Math.pow(1 + rate, y);
      rows.push({ year: y, invested: tax * g, pv: tax / g, benefit: tax - tax / g });
    }
    return { pv: pv, benefit: tax - pv, growth: tax * (growth - 1), wealth: stepUp ? tax * growth : tax * (growth - 1), rows: rows };
  }

  var IDS = ['lkdTaxDeferred', 'lkdBenefit', 'lkdGain', 'lkdEffRate', 'lkdNote', 'lkdAdjBasis', 'lkdGainRow', 'lkdUnrecap', 'lkdLtGain',
    'lkdFedTax', 'lkdNiitTax', 'lkdStateTax', 'lkdTotalTax', 'lkdPvTax', 'lkdBenefitRow', 'lkdGrowth', 'lkdWealth', 'lkdDeductUsed'];

  function update() {
    var status = el('lkdStatus').value;
    if (!BRACKETS[status]) status = 'single';
    var dedRaw = read('lkdDeduct', true);
    var p = {
      sale: read('lkdSale'), cost: read('lkdCost'), improve: read('lkdImprove', true), dep: read('lkdDep', true),
      sellCost: read('lkdSellCost', true), status: status, income: read('lkdIncome', true),
      deduction: String(el('lkdDeduct').value).trim() === '' ? STANDARD_DEDUCTION[status] : dedRaw,
      stateRate: read('lkdState', true) / 100, niit: el('lkdNiit').value === 'yes'
    };
    var years = read('lkdYears'), rate = read('lkdRate', true), stepUp = el('lkdEnd').value === 'stepup';
    var err = el('lkdError'), msg = '';
    if (isNaN(p.sale) || p.sale <= 0) msg = 'Enter the price you expect to sell the property for.';
    else if (isNaN(p.cost) || p.cost < 0) msg = 'Enter what you originally paid for the property ($0 or more).';
    else if ([p.improve, p.dep, p.sellCost, p.income, p.deduction].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts cannot be negative.';
    else if (p.dep > p.cost + p.improve) msg = 'Depreciation cannot be more than the cost plus improvements.';
    else if (isNaN(p.stateRate) || p.stateRate < 0 || p.stateRate > STATE_RATE_MAX / 100) msg = 'Enter a state tax rate from 0% to ' + STATE_RATE_MAX + '%.';
    else if (isNaN(years) || years < 1 || years > 50 || Math.round(years) !== years) msg = 'Enter a holding period of 1 to 50 whole years.';
    else if (isNaN(rate) || rate < 0 || rate > 20) msg = 'Enter a return from 0% to 20%.';
    else if ([p.sale, p.cost, p.improve, p.dep, p.sellCost, p.income, p.deduction].some(function (v) { return v > 1e11; })) msg = 'Amounts are too large.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); el('lkdRows').innerHTML = ''; return; }

    var t = saleTax(p);
    var d = deferral(t.total, rate / 100, years, stepUp);
    setText('lkdTaxDeferred', money.format(t.total));
    setText('lkdBenefit', money.format(d.benefit));
    setText('lkdGain', t.gain < 0 ? '−' + money.format(-t.gain) : money.format(t.gain));
    setText('lkdEffRate', t.gain > 0 ? pctFmt.format(t.total / t.gain) : '–');
    setText('lkdDeductUsed', money.format(p.deduction) + (String(el('lkdDeduct').value).trim() === '' ? ' (' + TAX_YEAR + ' standard deduction)' : ''));
    setText('lkdAdjBasis', money.format(t.adjBasis));
    setText('lkdGainRow', t.gain < 0 ? '−' + money.format(-t.gain) : money.format(t.gain));
    setText('lkdUnrecap', money.format(t.u));
    setText('lkdLtGain', money.format(t.c));
    setText('lkdFedTax', money.format(t.fed));
    setText('lkdNiitTax', money.format(t.niit));
    setText('lkdStateTax', money.format(t.state));
    setText('lkdTotalTax', money.format(t.total));
    setText('lkdPvTax', money.format(d.pv));
    setText('lkdBenefitRow', money.format(d.benefit));
    setText('lkdGrowth', money.format(d.growth));
    setText('lkdWealth', money.format(d.wealth));

    var note;
    if (t.gain <= 0) note = 'Selling at this price realizes no gain, so there is no tax to defer. A loss is not deductible in an exchange; selling outright would let you claim it instead.';
    else if (stepUp) note = 'Exchanging keeps ' + money.format(t.total) + ' of tax invested. If you hold the replacement property until death, your heirs get a stepped-up basis and the deferred tax is never paid, so the whole amount is saved.';
    else note = 'Exchanging keeps ' + money.format(t.total) + ' of tax invested for ' + years + (years === 1 ? ' year' : ' years') + '. Paying it then instead of now is worth ' +
      money.format(d.benefit) + ' in today’s money at a ' + rate + '% return, and the money kept invested grows by ' + money.format(d.growth) + ' before the tax comes due.';
    setText('lkdNote', note);

    el('lkdRows').innerHTML = t.gain <= 0 ? '' : d.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + money.format(row.invested) + '</td><td>' + money.format(row.pv) + '</td><td>' + money.format(row.benefit) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('lkdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
